WITH RECURSIVE x13 AS (SELECT 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) UNION ALL SELECT x11.v19166 + 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) FROM x14 WHERE x11.v19166 < 10000) SELECT x11.v19168, x11.v19166, ROUND(x11.v19167, x11.v19168) AS x3, x11.v19168 FROM v19165 AS x11 WHERE x11.v19168 > 95 ORDER BY RAND()